 'use strict';
const commonSecond={weaponMastery:{name:'Weapon Mastery',max:10,type:'passive',desc:'เพิ่มความชำนาญอาวุธ ดาเมจเสถียรและพลังโจมตีเพิ่ม'},finalAttack:{name:'Final Attack',max:20,type:'passive',desc:'มีโอกาสโจมตีเพิ่มเติมหลังโจมตีโดน',requires:{weaponMastery:3}},physicalTraining:{name:'Physical Training',max:5,type:'passive',desc:'เพิ่ม STR และ DEX ถาวร'},weaponAcceleration:{name:'Weapon Acceleration',max:10,type:'passive',desc:'เพิ่ม STR และลดช่วงห่างการโจมตีปกติ',requires:{weaponMastery:5}}};
const SECOND_SKILLS={greatsword:{...commonSecond,flashSlash:{name:'Flash Slash',max:9,type:'active',desc:'พุ่งไปตามทิศลูกศร พร้อมฟันศัตรูระหว่างทาง'},brandish:{name:'Brandish',max:20,type:'active',desc:'ฟันศัตรูด้านหน้า 2 ครั้ง สูงสุด 6 ตัว'},spiritBlade:{name:'Spirit Blade',max:20,type:'active',desc:'เพิ่ม ATK ติดตัว และสะท้อนดาเมจใส่ศัตรูถาวร'},comboAttack:{name:'Combo Attack',max:1,type:'active',desc:'สะสมอัตโนมัติคอมโบสูงสุด 5 ลูก เพิ่มดาเมจลูกละ 4%'}},guardian:{...commonSecond,divineSwing:{name:'Divine Swing',max:20,type:'active',desc:'ฟันพลังศักดิ์สิทธิ์และทำให้ศัตรูทั่วไปติดสตัน'},holyForce:{name:'Holy Force',max:1,type:'active',desc:'พลังศักดิ์สิทธิ์ติดตัว สะสมสูงสุด 5 ชั้น เพิ่มดาเมจและ DEF'},pageOrder:{name:'Page Order',max:9,type:'active',desc:'ดึงศัตรูรอบตัวให้เข้ามาและทำให้เดินช้าลง'},stance:{name:'Stance',max:20,type:'passive',desc:'เพิ่มโอกาสต้านการกระเด็น'}},spearman:{...commonSecond,ironWall:{name:'Iron Wall',max:9,type:'active',desc:'เพิ่ม DEF ติดตัว ถาวร'},hyperBody:{name:'Hyper Body',max:10,type:'active',desc:'เพิ่ม HP ติดตัว และ MP สูงสุดถาวร',requires:{ironWall:3}},beholder:{name:'Beholder',max:1,type:'active',desc:'ผู้ช่วย Beholder ติดตัว ฟื้นฟู HP ทุก 5 วินาที'},beholderShock:{name:'Beholder Shock',max:10,type:'active',desc:'ให้ Beholder โจมตีรอบตัวและสตัน ต้องเรียน Beholder ก่อน'},spearPulling:{name:'Spear Pulling',max:9,type:'active',desc:'กวาดหอกดึงศัตรูและทำให้ติดสตัน'}}};
function secondSkillTree(job=player.job){return SECOND_SKILLS[job]||{}}
function allSkillDefinitions(p=player){return {...SWORD_SKILLS,...(SECOND_SKILLS[p.job]||{})}}
function skillRank(id,p=player){return p.swordSkills?.[id]??p.secondSkills?.[id]??0}
function validateSecondSkills(raw,job){const out=Object.fromEntries(Object.keys(SECOND_SKILLS[job]||{}).map(k=>[k,0]));if(raw===undefined)return out;if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('สกิลขั้น 2 ไม่ถูกต้อง');for(const key of Object.keys(raw)){if(!Object.hasOwn(out,key))throw Error('สกิลไม่ตรงอาชีพ');const v=raw[key];if(!Number.isInteger(v)||v<0||v>SECOND_SKILLS[job][key].max)throw Error('เลเวลสกิลขั้น 2 ไม่ถูกต้อง');out[key]=v}return out}
function secondRequirementsMet(id,p=player){const def=SECOND_SKILLS[p.job]?.[id];return !!def&&Object.entries(def.requires||{}).every(([k,lv])=>(p.secondSkills?.[k]||0)>=lv)}
function secondInfo(id,lv){const base={cost:0,multiplier:0,targets:0,reach:180,hits:1};if(id==='brandish')return {...base,cost:10+Math.floor(lv/5),multiplier:.8+.04*lv,targets:6,hits:2};if(id==='flashSlash')return {...base,cost:8,multiplier:1.2+.1*lv,targets:6,reach:220};if(id==='divineSwing')return {...base,cost:10,multiplier:1.2+.06*lv,targets:6};if(id==='pageOrder'||id==='spearPulling')return {...base,cost:9,multiplier:1+.08*lv,targets:6,reach:220};if(id==='beholderShock')return {...base,cost:10,multiplier:1.5+.1*lv,targets:8,reach:210};if(['spiritBlade','ironWall','hyperBody'].includes(id))return {...base,cost:12,duration:45};return base}
function secondDescription(id,lv){if(id==='weaponMastery')return 'ATK +'+lv+'% · ความชำนาญอาวุธเพิ่ม';if(id==='finalAttack')return 'โอกาส '+lv*2+'% · ตีเสริม '+Math.round((.5+.03*lv)*100)+'% ATK';if(id==='physicalTraining')return 'STR +'+lv*2+' · DEX +'+lv;if(id==='weaponAcceleration')return 'STR +'+lv+' · โจมตีปกติเร็วขึ้น '+lv*2.5+'%';if(id==='stance')return 'ต้านกระเด็น '+lv*4+'%';if(id==='comboAttack')return 'ติดตัว · สูงสุด 5 ลูก · ดาเมจ +4% / ลูก';if(id==='holyForce')return 'ติดตัว · สูงสุด 5 ชั้น · ดาเมจ +3% และ DEF +2 / ชั้น';if(id==='beholder')return 'ติดตัว · ฟื้นฟู HP 5% ทุก 5 วินาที';if(id==='spiritBlade')return 'ติดตัว · ATK +'+lv*2+' · สะท้อน '+lv+'%';if(id==='ironWall')return 'ติดตัว · DEF +'+lv*2+'';if(id==='hyperBody')return 'ติดตัว · HP สูงสุด +'+lv*2+'% · MP สูงสุด +'+lv*3+'%';const info=secondInfo(id,Math.max(1,lv));return Math.round(info.multiplier*100)+'% ATK × '+info.hits+' ครั้ง · '+info.targets+' เป้าหมาย · MP '+info.cost+(id==='beholderShock'?' · ต้องเรียน Beholder':'')}
function secondBonuses(p=player){const s=p.secondSkills||{},buffs=p.buffs||{},charge=(s.holyForce||0)>0?Math.min(5,p.holyCharges||0):0;return {str:(s.physicalTraining||0)*2+(s.weaponAcceleration||0),dex:s.physicalTraining||0,atk:(s.spiritBlade||0)>0?(s.spiritBlade||0)*2:0,def:((s.ironWall||0)>0?(s.ironWall||0)*2:0)+charge*2,hpFactor:(s.hyperBody||0)>0?1+(s.hyperBody||0)*.02:1,mpFactor:(s.hyperBody||0)>0?1+(s.hyperBody||0)*.03:1,damageFactor:1+(s.weaponMastery||0)*.01+((s.comboAttack||0)>0?Math.min(5,p.comboOrbs||0)*.04:0)+charge*.03,stance:(s.stance||0)*.04}}
function resetSecondEffects(){player.buffs={};player.comboEnabled=false;player.comboOrbs=0;player.holyEnabled=false;player.holyCharges=0;player.beholderEnabled=false;player.beholderTimer=0;player.secondDash=null}
function onSecondHit(m,base){if(player.secondSkills?.comboAttack&&Math.random()<.6)player.comboOrbs=Math.min(5,(player.comboOrbs||0)+1);if(player.secondSkills?.holyForce)player.holyCharges=Math.min(5,(player.holyCharges||0)+1);const lv=player.secondSkills?.finalAttack||0;if(!m.dead&&lv&&Math.random()<lv*.02)hitMonster(m,attackPower()*(.5+lv*.03),false)}
function secondStrike(id,lv,seen){const info=secondInfo(id,lv),radial=['pageOrder','beholderShock','spearPulling'].includes(id);const targets=monsters.filter(m=>!m.dead&&player.y>m.y-monsterHeight(m)-15&&player.y<m.y+46&&(radial?Math.abs(m.x-player.x)<info.reach:(m.x-player.x)*player.face>=-monsterRadius(m)&&(m.x-player.x)*player.face<info.reach)).sort((a,b)=>Math.abs(a.x-player.x)-Math.abs(b.x-player.x)).slice(0,info.targets);for(const m of targets){if(seen?.has(m))continue;seen?.add(m);for(let i=0;i<info.hits&&!m.dead;i++)hitMonster(m,attackPower()*jobProfile().multiplier*info.multiplier);if(!m.dead&&!m.boss&&!m.elite){if(['divineSwing','beholderShock','spearPulling'].includes(id))m.stun=1+lv*.03;if(['pageOrder','spearPulling'].includes(id)){m.x=clamp(player.x+(m.x>player.x?35:-35),m.low,m.high);m.slow=3}}}swordSwipes.push({x:player.x,y:player.y-20,face:player.face,reach:info.reach,life:.3,key:id});burst(player.x,player.y-20,player.job==='guardian'?'#f2e5a8':'#a5dafa',14);tutorialMark('attack')}
function castSecondSkill(id){const tree=secondSkillTree(),def=tree[id],lv=player.secondSkills?.[id]||0;if((player.cd.action||0)>0||paused||screen!=='play'||run?.finished||!def||def.type!=='active'||!lv||!secondRequirementsMet(id))return false;const info=secondInfo(id,lv);if(player.mp<info.cost||id==='beholderShock'&&!player.secondSkills?.beholder)return false;beginActionDelay(id);player.mp-=info.cost;player.buffs??={};if(id==='comboAttack'){player.comboEnabled=!player.comboEnabled;player.comboOrbs=0}else if(id==='holyForce'){player.holyEnabled=!player.holyEnabled;player.holyCharges=0}else if(id==='beholder'){player.beholderEnabled=!player.beholderEnabled;player.beholderTimer=0}else if(info.duration)player.buffs[id]=info.duration;else{if(id==='flashSlash'){let dx=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0),dy=(keys.ArrowDown?1:0)-(keys.ArrowUp?1:0);if(!dx&&!dy)dx=player.face;const length=Math.hypot(dx,dy);player.dashV=dx/length*(420+lv*12);player.dashTime=.2;if(dy){player.ground=false;player.climbing=false;player.vy=dy/length*360}player.secondDash={id,lv,seen:new Set()};secondStrike(id,lv,player.secondDash.seen)}else secondStrike(id,lv)}tone(440,.12,'triangle');updateUI();return true}
function tickSecondSkills(dt){for(const key of Object.keys(player.buffs||{}))player.buffs[key]=Math.max(0,player.buffs[key]-dt);if(player.secondSkills?.beholder){player.beholderTimer=(player.beholderTimer||0)+dt;if(player.beholderTimer>=5){player.beholderTimer-=5;player.hp=Math.min(maxHP(),player.hp+Math.ceil(maxHP()*.05));burst(player.x,player.y-20,'#b4e5ba',7)}}if(player.secondDash){if(player.dashTime>0)secondStrike(player.secondDash.id,player.secondDash.lv,player.secondDash.seen);else player.secondDash=null}}
function drawBeholder(){if(!player.secondSkills?.beholder)return;const x=player.x-player.face*34,y=player.y-64+Math.sin(time*3)*5;ellipse(x,y,12,10,'#c4b6f0');ellipse(x,y,7,7,'#eee9fc');ellipse(x+player.face*2,y,3,4,'#4d386b')}

for(const [job,tree]of Object.entries(SECOND_SKILLS)){const active={greatsword:["brandish","flashSlash"],guardian:["divineSwing","pageOrder"],spearman:["spearPulling","beholderShock"]}[job];for(const [id,def]of Object.entries(tree))def.type=active.includes(id)?"active":"passive"}
